def ro(path,old,new,label):
    p=Path(path); s=p.read_text(); n=s.count(old)
    if n!=1: raise SystemExit(f'{label}: expected 1 match, got {n} in {p}')
    p.write_text(s.replace(old,new,1))

def ins(path,anchor,block,label):
    ro(path,anchor,block+anchor,label)

